type RfqStatus = "Draft" | "Not Started" | "Live" | "Negotiation Scheduled" | "Negotiation Ended" | "QCS Created" | "QCS Pending" | "QCS Approved" | "PO Approved" | "PO Processed" | "PO Completed" | "Quotations Pending" | "Quotations Received" | "Approved" | string;
type Rfq = {
  id: string; number: string; title: string; reqId: string; prNo?: string | null; department?: string | null;
  createdBy?: string; template?: string; type?: string; status: RfqStatus; urgency?: string; currency: string;
  startAt?: string | null; endAt?: string | null; freezeAt?: string | null; expectedStartAt?: string | null;
  project?: string | null; client?: string | null; incoTerms?: string | null; paymentTerms?: string | null;
  deliveryTerms?: string | null; biddingType?: string; aiScoring?: boolean; settings?: Record<string, unknown>;
  createdAt: string; updatedAt?: string; itemCount?: number; vendorCount?: number;
};
type Vendor = { id: string; company: string; code: string; contact?: string | null; email?: string | null; phone?: string | null; score: string | number; };
type RfqItem = { id: string; rfqId: string; name: string; code: string; partNo?: string | null; uom: string; qty: string | number; specs?: string | null; targetPrice?: string | null; };
type Quote = { id: string; rfqId: string; vendorId: string; status: string; initialTotal: string | number; finalTotal: string | number; otherCharges: string | number; rank?: number | null; comment?: string | null; updatedAt?: string; vendor: Vendor; };
type Bid = { id: string; rfqId: string; vendorId: string; itemId: string | null; unitPrice: string | number; kind: string; createdAt: string; vendor: Vendor; item: RfqItem | null; };
type PurchaseOrder = { id: string; itemCode: string; poNumber: string; vendorName: string; description: string; price: string | number; currency: string; orderedAt: string; };
type AuditLog = { id: string; actorId: string; action: string; details: Record<string, unknown>; reason?: string | null; createdAt: string; };
type RfqDetail = { rfq: Rfq; items: RfqItem[]; quotes: Quote[]; bids: Bid[]; auditLogs: AuditLog[]; comments: Array<{ id: string; actorId: string; message: string; createdAt: string; vendor?: Vendor | null }>; counterBids: Array<{ id: string; version: number; unitPrice: string | number; status: string; comment?: string | null; createdAt: string; vendor: Vendor; item: RfqItem }>; purchaseOrders: PurchaseOrder[]; };
type Screen = "dashboard" | "requirements" | "auctions" | "qcs" | "vendors" | "history" | "reports" | "analytics" | "settings" | "detail" | "comparative" | "vendorPortal";
type ModalState = { type: "create" } | { type: "approve"; vendorId: string } | { type: "rollback"; vendorId: string } | { type: "surrogate"; vendorId?: string } | { type: "priceCap" } | { type: "comment"; vendorId?: string } | { type: "help" } | null;
type LineDraft = { key: string; name: string; code: string; partNo: string; uom: string; qty: string; specs: string; targetPrice: string };
type AiMessage = { role: "assistant" | "user"; text: string };

